int bfs() {
  queue<pair<int,int>> q;
  q.push({0, 0});
  dist[0][0] = 1;
  while (!q.empty()) {
    auto [x, y] = q.front(); q.pop();
    for (int d = 0; d < 4; d++) {
      int nx = x + dx[d], ny = y + dy[d];
      if (nx < 0 || ny < 0 || nx >= n || ny >= m) continue;
      if (board[nx][ny] == '0' || dist[nx][ny]) continue;
      dist[nx][ny] = dist[x][y] + 1;
      q.push({nx, ny});
    }
  }
  return dist[n-1][m-1];
}
